const setupCommand = async () => {
  console.log("Setting up ConsolesAI...");

  const homeDir = os.homedir();
  const envPath = path.join(homeDir, ".consoles.env");

  let token, apiKey;

  if (fs.existsSync(envPath)) {
    console.log(".consoles.env file found at 📁 " + envPath);
    const envVars = readEnvFile(envPath);

    if (envVars.TOKEN) {
      token = envVars.TOKEN;
      console.log("Using existing token: 🔑 " + token);
