const readEnvFile = (envPath) => {
  const envContent = fs.readFileSync(envPath, "utf-8");
  return Object.fromEntries(
    envContent
      .split("\n")
      .filter(Boolean)
      .map((line) => line.split("="))
  );
};

const extractMatches = (regex, content, type) => {
  const matches = [];
  let match;
  while ((match = regex.exec(content)) !== null) {
    if (type === "endpoint") {
      matches.push({ method: match[1], route: match[2] });
    } else if (type === "llm") {
      matches.push({ name: match[1] });
    }
  }
  return matches;
};

const deployProject = async (entryScript) => {
  console.log("├── 🔨 Building your project...");

  if (!fs.existsSync(entryScript)) {
    throw new Error(
      `   The entry script '${entryScript}' does not exist!\n`
    );
  }

  const fileContent = fs.readFileSync(entryScript, "utf8");
  const projectNameMatch = fileContent.match(/new Console\('([^']+)'\)/);

  if (!projectNameMatch) {
    throw new Error(
      `   No 'Console' instance found in the entry script '${entryScript}'! Please define a Console instance.`
    );
  }
  const projectName = projectNameMatch[1];
  const bundleDir = path.join(path.dirname(entryScript), "built");
  const bundlePath = path.join(bundleDir, `${projectName}_bundle.mjs`);

  if (!fs.existsSync(bundleDir)) {
    fs.mkdirSync(bundleDir);
  }

  // Read API key from .consoles.env file
  const homeDir = os.homedir();
  const envPath = path.join(homeDir, ".consoles.env");
  if (!fs.existsSync(envPath)) {
    throw new Error(
      `   The .consoles.env file does not exist at ${envPath}!\n`
    );
  }
  const envVars = readEnvFile(envPath);
  const apiKey = envVars.API_KEY;
  if (!apiKey) {
    throw new Error(
      `   The API_KEY is not defined in the .consoles.env file!\n`
    );
  }

  let modifiedFileContent = fileContent;

  const apiKeyRegex = /new Console\('([^']+)'\s*,\s*'([^']+)'\);/;
  if (!apiKeyRegex.test(fileContent)) {
    modifiedFileContent = fileContent.replace(
      /new Console\('([^']+)'\);/,
      `new Console('$1', '${apiKey}');`
    );
  }

  fs.writeFileSync(entryScript, modifiedFileContent, "utf8");

  try {
    const scriptDir = path.dirname(entryScript);
    await esbuild.build({
      entryPoints: [entryScript],
      bundle: true,
      outfile: bundlePath,
      platform: "node",
      external: [],
      minify: false,
      sourcemap: false,
      format: "esm",
      target: ["node14"],
      loader: { ".ts": "ts" },
      tsconfig: path.join(path.dirname(scriptDir), "tsconfig.json"),
    });
    console.log("├── 📦 Building completed.");
    const bundleContent = fs.readFileSync(bundlePath, "utf8");

    const endpoints = extractMatches(
      /app\.(get|post|put|delete|patch)\(['\"`](.*?)['\"`]/g,
      bundleContent,
      "endpoint"
    );
    const llms = extractMatches(
      /app\.llm\s*\(\s*['\"`](.*?)['\"`]\s*\)/g,
      bundleContent,
      "llm"
    );

    console.log("├── ✨ Deploying to cloud...");
    const response = {
      data: {
        id: crypto.randomBytes(3).toString("hex"),
        deploymentId: crypto.randomBytes(3).toString("hex"),
        projectName: projectName,
        workspace: "cosmo",
        endpoints: endpoints,
        llm: llms,
      },
    };
    console.log("├── 🌍 Deployment completed.");

    return response.data;
  } catch (error) {
    console.error("❌ Error during deployment: " + error.message);
    throw error;
  }
};

